const entry=document.getElementById('entry');
const result=document.getElementById('result');
const errEl=document.getElementById('error');
const statusEl=document.getElementById('status');
const histEl=document.getElementById('history');
const emptyEl=document.getElementById('empty');
const clearBtn=document.getElementById('clearHistory');
let history=[];let revs={};

function calc(src){
  const s=src.replace(/×/g,'*').replace(/÷/g,'/').replace(/−/g,'-').replace(/,/g,'.').replace(/\s+/g,'');
  if(!s)throw new Error('Type a calculation first.');
  let i=0;
  function fail(){throw new Error('That calculation is not valid. Check the numbers and symbols.');}
  function expr(){let v=term();while(s[i]==='+'||s[i]==='-'){const o=s[i++];const r=term();v=o==='+'?v+r:v-r;}return v;}
  function term(){let v=unary();while(s[i]==='*'||s[i]==='/'){const o=s[i++];const r=unary();if(o==='/'&&r===0)throw new Error('You can\'t divide by zero.');v=o==='*'?v*r:v/r;}return v;}
  function unary(){if(s[i]==='-'){i++;return -unary();}if(s[i]==='+'){i++;return unary();}return power();}
  function power(){let b=post();if(s[i]==='^'){i++;const e=unary();return Math.pow(b,e);}return b;}
  function post(){let v=atom();while(s[i]==='%'){i++;v=v/100;}return v;}
  function atom(){
    if(s[i]==='('){i++;const v=expr();if(s[i]!==')')fail();i++;return v;}
    const m=/^\d*\.?\d+(?:e[+-]?\d+)?|^\d+\.?/i.exec(s.slice(i));
    if(!m)fail();
    i+=m[0].length;return parseFloat(m[0]);
  }
  const v=expr();
  if(i<s.length)fail();
  if(!isFinite(v))throw new Error('The answer is too large to show.');
  return String(parseFloat(v.toPrecision(12)));
}

function renderHistory(){
  histEl.textContent='';
  const items=history.slice(-10).reverse();
  for(const h of items){
    const li=document.createElement('li');
    li.textContent=h.expression+' = '+h.answer;
    histEl.appendChild(li);
  }
  emptyEl.hidden=items.length>0;
  clearBtn.hidden=history.length===0;
}
async function load(){
  try{
    const r=await tessera.call('data.read',{});
    history=Array.isArray(r.data.history)?r.data.history:[];
    revs=(r.revisions&&r.revisions.history)||{};
  }catch(e){statusEl.textContent='Recent calculations could not be loaded.';}
  renderHistory();
}
async function run(){
  errEl.textContent='';statusEl.textContent='';
  let ans;const expression=entry.value.trim();
  try{ans=calc(expression);}catch(e){errEl.textContent=e.message;return;}
  result.textContent=ans;
  try{
    await tessera.call('data.patch',{operations:[{op:'add',collection:'history',record:{expression:expression,answer:ans}}]});
    await load();
  }catch(e){statusEl.textContent='The answer is shown, but it could not be added to recent calculations.';}
}
document.getElementById('equals').addEventListener('click',run);
entry.addEventListener('keydown',function(ev){if(ev.key==='Enter'){ev.preventDefault();run();}});

const keyList=['7','8','9','÷','4','5','6','×','1','2','3','−','0','.','(',')','%','^','⌫','C','+'];
const names={'÷':'divide','×':'multiply','−':'minus','+':'plus','⌫':'Backspace','C':'Clear','(':'Open bracket',')':'Close bracket','^':'Power','%':'Percent','.':'Decimal point'};
const keysEl=document.getElementById('keys');
for(const k of keyList){
  const b=document.createElement('button');
  b.type='button';b.textContent=k;
  if(names[k])b.setAttribute('aria-label',names[k]);
  b.addEventListener('click',function(){
    errEl.textContent='';
    if(k==='C'){entry.value='';result.textContent='0';}
    else if(k==='⌫'){entry.value=entry.value.slice(0,-1);}
    else{entry.value+=k;}
    entry.focus();
  });
  keysEl.appendChild(b);
}
clearBtn.addEventListener('click',async function(){
  try{
    const ops=history.map(function(h){return{op:'remove',collection:'history',id:h.id,revisionCount:revs[h.id]};});
    if(ops.length){await tessera.call('data.patch',{operations:ops});}
    statusEl.textContent='Recent calculations cleared.';
    await load();
    entry.focus();
  }catch(e){statusEl.textContent='Could not clear recent calculations. Try again.';}
});
load();

